Let $\ensuremath{\mathpzc{V}}\xspace$ be a complete and cocomplete symmetric closed monoidal category. Consider $\ensuremath{\mathpzc{V}}\xspace$-functors $F\:\ensuremath{\mathpzc{A}}\xspace \to \ensuremath{\mathpzc{C}}\xspace$ (the diagram) and $W\:\ensuremath{\mathpzc{A}}\xspace\to \ensuremath{\mathpzc{V}}\xspace$ (the weight), with $\ensuremath{\mathpzc{A}}\xspace$ a small $\ensuremath{\mathpzc{V}}\xspace$-category. The {\itshape $\ensuremath{\mathpzc{V}}\xspace$-limit of $F$ weighted by $W$}, denoted as ${\lim}^{W}\hspace{1.0\horspace}{F}$, is (if it exists) an object $L\in \ensuremath{\mathpzc{C}}\xspace$ together with an isomorphism in \ensuremath{\mathpzc{V}}\xspace
 	\begin{equation}\label{isoweightlim}
 		{\ensuremath{\mathpzc{C}}\xspace}\left({U},\hspace{1\horspace}{L}\right)\cong {\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{V}}\xspace\right]}\xspace}\left({W},\hspace{1\horspace}{{\ensuremath{\mathpzc{C}}\xspace}\left({U},\hspace{1\horspace}{F(-)}\right)}\right)
 	\end{equation}
 	$\ensuremath{\mathpzc{V}}\xspace$-natural in $U\in \ensuremath{\mathpzc{C}}\xspace\ensuremath{^{\operatorname{op}}}$, where $\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{V}}\xspace\right]}\xspace$ is the $\ensuremath{\mathpzc{V}}\xspace$-category of $\ensuremath{\mathpzc{V}}\xspace$-copresheaves on $\ensuremath{\mathpzc{A}}\xspace$ valued in $\ensuremath{\mathpzc{V}}\xspace$ enriched over itself. When ${\lim}^{W}\hspace{1.0\horspace}{F}$ exists, the identity on $L$ provides a $\ensuremath{\mathpzc{V}}\xspace$-natural transformation $\lambda\:W 
	\ext@arrow 0055{\Rightarrowfill@}{}{}{\ensuremath{\mathpzc{C}}\xspace}\left({L},\hspace{1\horspace}{F(-)}\right)$ called the {\itshape universal cylinder}.

 	For the notion of {\itshape weighted $\ensuremath{\mathpzc{V}}\xspace$-colimit}, we start from $F\:\ensuremath{\mathpzc{A}}\xspace\to\ensuremath{\mathpzc{C}}\xspace$ and $W\:\ensuremath{\mathpzc{A}}\xspace\ensuremath{^{\operatorname{op}}}\to\ensuremath{\mathpzc{V}}\xspace$. The universal property is then
 	\begin{equation*}
 		{\ensuremath{\mathpzc{C}}\xspace}\left({{\operatorname{colim}}^{W}\hspace{1.0\horspace}{F}},\hspace{1\horspace}{U}\right)\cong {\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace\ensuremath{^{\operatorname{op}}},\ensuremath{\mathpzc{V}}\xspace\right]}\xspace}\left({W},\hspace{1\horspace}{{\ensuremath{\mathpzc{C}}\xspace}\left({F(-)},\hspace{1\horspace}{U}\right)}\right)
 	\end{equation*}

	Although the classical constant at $1$ weight $\Delta 1$, called the {\itshape conical weight}, no longer suffices in the general enriched setting, we pay attention to when a weighted limit can be {\itshape reduced to a conical one}. It is well known (see Kelly's~\cite{kelly_basicconceptsofenriched}) that in the $\ensuremath{\mathpzc{Set}}\xspace$-enriched setting every weighted limit can be conicalized, using the category of elements. A general strategy of conicalization (used by Kelly in~\cite{kelly_basicconceptsofenriched}) allows to conicalize just the $\ensuremath{\mathpzc{V}}\xspace$-colimits $W\cong {\operatorname{colim}}^{W}\hspace{1.0\horspace}{\operatorname{y}}$, for $W\:\ensuremath{\mathpzc{A}}\xspace\to \ensuremath{\mathpzc{V}}\xspace$ an enriched presheaf with $\ensuremath{\mathpzc{A}}\xspace$ small and $\operatorname{y}\:\ensuremath{\mathpzc{A}}\xspace\ensuremath{^{\operatorname{op}}}\to\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{V}}\xspace\right]}\xspace$ the $\ensuremath{\mathpzc{V}}\xspace$-Yoneda embedding. The lemma of continuity of a limit in its weight then allows to deduce that all weighted limits are conicalized. The formula is
	\begin{equation}\label{isolemmacont}
		{\lim}^{{\operatorname{colim}}^{W}\hspace{1.0\horspace}{H}}\hspace{1.0\horspace}{F} \cong {\lim}^{W}\hspace{1.0\horspace}{\left({\lim}^{H(-)}\hspace{1.0\horspace}{F}\right)}
	\end{equation}

\label{defexpltwosetgroth}
	Let $F\:\ensuremath{\mathpzc{B}}\xspace\to\ensuremath{\mathpzc{Cat}}\xspace$ be a $2$-functor with $\ensuremath{\mathpzc{B}}\xspace$ a $2$-category. The {\itshape $2$-category of elements of $F$} is the $2$-functor $\mathcal{G}\mkern-1.4mu\left(F\right)\:\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} F}\to \ensuremath{\mathpzc{B}}\xspace$, given by the projection on the first component, with $\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} F}$ such that:
	\begin{description}
		\item[an object of $\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} F}$] is a pair $(B,X)$ with $B\in \ensuremath{\mathpzc{B}}\xspace$ and $X\in F(B)$;
		\item[a morphism $(B,X)\to (C,X')$ in $\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} F}$] is a pair $(f,\alpha)$ with $f\:B\to C$ a morphism in $\ensuremath{\mathpzc{B}}\xspace$ and $\alpha\:F(f)(X)\to X'$ a morphism in $F(C)$;
		\item[a $2$-cell $(f,\alpha) 
	\ext@arrow 0055{\Rightarrowfill@}{}{}(g,\beta)\:(B,X)\to (C,X')$ in $\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} W}$] is a $2$-cell $\delta\:f 
	\ext@arrow 0055{\Rightarrowfill@}{}{}g$ in $\ensuremath{\mathpzc{B}}\xspace$ such that $\alpha=\beta\circ F(\delta)_X$;
		\item[the compositions and identities] are as described in \textrm{Construction}~\ref{2SetGrothconstrtoconicalize}.
	\end{description}

\label{deftwosetopf}
		Let $\ensuremath{\mathpzc{B}}\xspace$ be a $2$-category. A {\itshape discrete $2$-opfibration over $\ensuremath{\mathpzc{B}}\xspace$} is a $2$-functor $P\:\ensuremath{\mathpzc{E}}\xspace\to \ensuremath{\mathpzc{B}}\xspace$ such that
		\begin{enum}
			\item the underlying functor $P_0$ of $P$ is an ordinary Grothendieck opfibration;
			\item for every pair $X,Y\in \ensuremath{\mathpzc{E}}\xspace$ the functor $P_{X,Y}\:{\ensuremath{\mathpzc{E}}\xspace}\left({X},\hspace{1\horspace}{Y}\right)\to {\ensuremath{\mathpzc{B}}\xspace}\left({P(X)},\hspace{1\horspace}{P(Y)}\right)$ is a discrete fibration.
		\end{enum}
		We say that $P$ is {\itshape split} if $P_0$ is so.

\label{deflaxnormal}
		Let $W\:\ensuremath{\mathpzc{A}}\xspace\to \ensuremath{\mathpzc{Cat}}\xspace$ be a $2$-functor with $\ensuremath{\mathpzc{A}}\xspace$ small, and consider $2$-functors $M,N\:\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} W}\to \ensuremath{\mathpzc{D}}\xspace$. A {\itshape cartesian-marked lax natural transformation $\alpha$ from $M$ to $N$}, denoted $\alpha\:M 
	\ext@arrow 0055{\Rightarrowfill@}{\operatorname{lax^{cart}}}{}N$,\vspace{1.0\verspace}\xspace is a lax natural transformation $\alpha$ from $M$ to $N$ such that the structure $2$-cell on every morphism of the form $\big(\mkern1mu{f,\operatorname{id}_{W(f)(X)}}\mkern1mu\big)\:(A,X)\to (B,W(f)(X))$ in $\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} W}$ is the identity.

\label{laxnormalareweighted}
		Cartesian-marked lax conical limits are particular weighted $2$-limits. More precisely, given $2$-functors $Z\:\ensuremath{\mathpzc{A}}\xspace\to\ensuremath{\mathpzc{Cat}}\xspace$ and $F\:\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} Z}\to\ensuremath{\mathpzc{C}}\xspace$ with $\ensuremath{\mathpzc{A}}\xspace$ small, the weight that realizes $\operatorname{lax^{cart}}\mbox{-}\hspace{1.5\horspace}{\lim}^{\Delta 1}\hspace{1.0\horspace}{F}$ is
		\begin{fun}
			\operatorname{W}^{\operatorname{lax^{cart}}} & \: & \ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} Z} \hphantom{..}& \longrightarrow & \ensuremath{\mathpzc{Cat}}\xspace \\[1ex]
			&& \fib[n][3]{(B,X')}{(g,\beta)}{(C,X'')} &\mapsto & \fib[n][3]{{\raisebox{.1em}{$Z(B)$}\mkern-1mu\left/\raisebox{-.25em}{$X'$}\right.}}{\beta\circ Z(g)(-)}{{\raisebox{.1em}{$Z(C)$}\mkern-1mu\left/\raisebox{-.25em}{$X''$}\right.}}\\[4.8ex]
			&& (g,\beta) 
	\ext@arrow 0055{\Rightarrowfill@}{}{\delta}(h,\gamma) & \mapsto & Z(\delta)_{\operatorname{dom}(-)}
		\end{fun}
		where the action of $\beta\circ Z(g)(-)$ on morphisms\vspace{1.0\verspace}\xspace is given by $Z(g)(\operatorname{dom}(-))$.

By \textrm{Remark}~\ref{needoflaxcones}, we can just essentially conicalize the weighted $2$-colimits $W\cong {\operatorname{colim}}^{W}\hspace{1.0\horspace}{\operatorname{y}}$ with $W\:\ensuremath{\mathpzc{A}}\xspace\to \ensuremath{\mathpzc{Cat}}\xspace$ a $2$-copresheaf with $\ensuremath{\mathpzc{A}}\xspace$ small. It is straightforward to extend \textrm{Construction}~\ref{2SetGrothconstrtoconicalize} to an isomorphism of categories
		\begin{equation}\label{isoredlaxnormal}
			\scalebox{0.95}{${\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{Cat}}\xspace\right]}\xspace}\left({W},\hspace{1\horspace}{{\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{Cat}}\xspace\right]}\xspace}\left({\ensuremath{\operatorname{y}\hspace{-0.2ex}\left({-}\right)}},\hspace{1\horspace}{U}\right)}\right)\cong {\ensuremath{\left[\ensuremath{{\scalebox{1.2}{$\int$}}\ensuremath{^{\operatorname{op}}} \hspace{-0.15ex} W},\ensuremath{\mathpzc{Cat}}\xspace\right]_{\operatorname{lax^{cart}}}}\xspace}\left({\Delta 1},\hspace{1\horspace}{{\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{Cat}}\xspace\right]}\xspace}\left({{\left(\operatorname{y}\circ\hspace{1.0\horspace}{\mathcal{G}\mkern-1.4mu\left(W\right)}\ensuremath{^{\operatorname{op}}}\right)}(-)},\hspace{1\horspace}{U}\right)}\right)$}
		\end{equation}
		$2$-natural in $U\in\ensuremath{\left[\ensuremath{\mathpzc{A}}\xspace,\ensuremath{\mathpzc{Cat}}\xspace\right]}\xspace$, expressing
		$$W\cong {\operatorname{colim}}^{W}\hspace{1.0\horspace}{\operatorname{y}}\cong \operatorname{lax^{cart}}\mbox{-}\hspace{1.5\horspace}{\operatorname{colim}}^{\Delta 1}\hspace{1.0\horspace}{\left(\operatorname{y}\circ\hspace{1.0\horspace}{\mathcal{G}\mkern-1.4mu\left(W\right)}\ensuremath{^{\operatorname{op}}}\right)}.$$

		Consider now $2$-functors $F\:\ensuremath{\mathpzc{A}}\xspace\to\ensuremath{\mathpzc{C}}\xspace$ and $W\:\ensuremath{\mathpzc{A}}\xspace\to\ensuremath{\mathpzc{Cat}}\xspace$ with $\ensuremath{\mathpzc{A}}\xspace$ small. Then by the argument above and \textrm{Corollary}~\ref{laxnormalcolimareweighted}
		$$W\cong \operatorname{lax^{cart}}\mbox{-}\hspace{1.5\horspace}{\operatorname{colim}}^{\Delta 1}\hspace{1.0\horspace}{\left(\operatorname{y}\circ\hspace{1.0\horspace}{\mathcal{G}\mkern-1.4mu\left(W\right)}\ensuremath{^{\operatorname{op}}}\right)}\cong {\operatorname{colim}}^{\operatorname{W}^{\operatorname{lax^{cart}}}}\hspace{1.0\horspace}{\left(\operatorname{y}\circ\hspace{1.0\horspace}{\mathcal{G}\mkern-1.4mu\left(W\right)}\ensuremath{^{\operatorname{op}}}\right)}.$$
		By the lemma of continuity of a limit in its weight (see \textrm{Remark}~\ref{needoflaxcones}) and \textrm{Theorem}~\ref{laxnormalareweighted},
		$${\lim}^{W}\hspace{1.0\horspace}{F}\cong{\lim}^{\operatorname{W}^{\operatorname{lax^{cart}}}}\hspace{1.0\horspace}{\left({\lim}^{\left(\operatorname{y}\circ\hspace{1.0\horspace} {\mathcal{G}\mkern-1.4mu\left(W\right)}\ensuremath{^{\operatorname{op}}}\right)(-)}\hspace{1.0\horspace}{F}\right)}\cong{\lim}^{\operatorname{W}^{\operatorname{lax^{cart}}}}\hspace{1.0\horspace}{\left(F\circ \mathcal{G}\mkern-1.4mu\left(W\right)\right)}\cong\operatorname{lax^{cart}}\mbox{-}\hspace{1.5\horspace}{\lim}^{\Delta 1}\hspace{1.0\horspace}{\left(F\circ \mathcal{G}\mkern-1.4mu\left(W\right)\right)}$$
		where the isomorphism in the middle is easy to prove.

\label{univlaxnormalcone}
		The proof of \textrm{Theorem}~\ref{redlaxnormalconical}, together with the proofs of \textrm{Theorem}~\ref{laxnormalareweighted} and \textrm{Corollary}~\ref{laxnormalcolimareweighted}, also shows how to obtain the correspondence between the universal cylinder of a weighted $2$-limit and the associated universal cartesian-marked lax cocone. Calling the two, respectively, 
		$$\lambda\:W 
	\ext@arrow 0055{\Rightarrowfill@}{}{} {\ensuremath{\mathpzc{C}}\xspace}\left({L},\hspace{1\horspace}{F(-)}\right) \text{\quad and \quad}\widehat{ 
	\mathpalette\douwidehat{\lambda} 
}\:\Delta 1  
	\ext@arrow 0055{\Rightarrowfill@}{\operatorname{lax^{cart}}}{} {\ensuremath{\mathpzc{C}}\xspace}\left({L},\hspace{1\horspace}{\left(F\circ \mathcal{G}\mkern-1.4mu\left(W\right)\right)(=)}\right)$$
		the correspondence is given, for every $(f,\alpha)\:(A,X)\to(B,X')$ in $\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} W}$, by
		\begin{equation}\label{lambdahats}
			\widehat{ 
	\mathpalette\douwidehat{\lambda} 
}_{(A,X)}=\lambda_A(X)\quad\text{ and }\quad\widehat{ 
	\mathpalette\douwidehat{\lambda} 
}_{(f,\alpha)}=\lambda_B(\alpha).
		\end{equation}

\label{remoplaxnormalvslaxnormal}
		As weighted $2$-colimits in $\ensuremath{\mathpzc{C}}\xspace$ are weighted $2$-limits in $\ensuremath{\mathpzc{C}}\xspace\ensuremath{^{\operatorname{op}}}$, we automatically obtain from \textrm{Theorem}~\ref{redlaxnormalconical} the reduction of weighted $2$-colimits to cartesian-marked lax conical ones. However, this considers the 2-category of elements $\mathcal{G}\mkern-1.4mu\left(W\right)\:\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} W}\to\ensuremath{\mathpzc{A}}\xspace\ensuremath{^{\operatorname{op}}}$ of the weight $W\:\ensuremath{\mathpzc{A}}\xspace\ensuremath{^{\operatorname{op}}}\to \ensuremath{\mathpzc{Cat}}\xspace$, rather than the more natural $\hspace{1.0\horspace}\mathcal{G}\mkern-1.4mu\left(W\right)\:\ensuremath{\int \hspace{-0.35ex} W}\to\ensuremath{\mathpzc{A}}\xspace$ with $\ensuremath{\int \hspace{-0.35ex} W}$ defined as follows:
		\begin{description}
			\item[an object of $\ensuremath{\int \hspace{-0.35ex} W}$] is a pair $(A,X)$ with $A\in \ensuremath{\mathpzc{A}}\xspace$ and $X\in F(A)$;
			\item[a morphism $(A,X)\to (B,X')$ in $\ensuremath{\int \hspace{-0.35ex} W}$] is a pair $(f,\alpha)$ with $f\:A\to B$ a morphism in $\ensuremath{\mathpzc{A}}\xspace$ and $\alpha\:X\to W(f)(X')$ a morphism in $W(A)$;
			\item[a $2$-cell $(f,\alpha) 
	\ext@arrow 0055{\Rightarrowfill@}{}{}(g,\beta)\:(A,X)\to (B,X')$ in $\ensuremath{\int \hspace{-0.35ex} W}$] is a $2$-cell $\delta\:f 
	\ext@arrow 0055{\Rightarrowfill@}{}{}g$ in $\ensuremath{\mathpzc{A}}\xspace$ such that $W(\delta)_{X'}\circ \alpha=\beta$.
		\end{description}
		We believe that it is more natural to reduce weighted $2$-limits to cartesian-marked lax conical ones and weighted $2$-colimits to {\itshape cartesian-marked oplax conical} ones. This idea is original and brings to \textrm{Theorem}~\ref{oplaxnormalareweighted} and \textrm{Theorem}~\ref{redoplaxnormalconical}.

\label{oplaxnormalareweighted}
		Cartesian-marked oplax conical $2$-colimits are particular weighted $2$-colimits. More precisely, given $2$-functors $Z\:\ensuremath{\mathpzc{A}}\xspace\ensuremath{^{\operatorname{op}}}\to\ensuremath{\mathpzc{Cat}}\xspace$ and $F\:\ensuremath{\int \hspace{-0.35ex} Z}\to\ensuremath{\mathpzc{C}}\xspace$ with $\ensuremath{\mathpzc{A}}\xspace$ small, the weight that realizes $\operatorname{oplax^{cart}}\mbox{-}\hspace{1.5\horspace}{\operatorname{colim}}^{\Delta 1}\hspace{1.0\horspace}{F}$ is
		\begin{fun}
			\operatorname{W}^{\operatorname{oplax^{cart}}} & \: & {\left(\ensuremath{\int \hspace{-0.35ex} Z}\right)}\ensuremath{^{\operatorname{op}}} \hphantom{.}& \longrightarrow & \ensuremath{\mathpzc{Cat}}\xspace \\[1ex]
			&& (B,X') &\mapsto & {\raisebox{.1em}{$X'$}\mkern-1mu\left/\raisebox{-.14em}{$Z(B)$}\right.}
		\end{fun}

\label{laxnatinsidegrothconstr}
		Let $F\:\ensuremath{\mathpzc{B}}\xspace\to \ensuremath{\mathpzc{Cat}}\xspace$ be a $2$-functor and consider its $2$-category of elements. There is a cartesian-marked lax natural transformation $\lambda$ of the form
		\begin{eqD*}


	\def\foosq##1##2##3##4##5##6##7##8{ 
		\IfBooleanTF{#1}{\begin{cd}*}{\begin{cd}}[#3][#4]
				{##1}\ifx#2p{\arrow[rd,phantom,"\scalebox{1.6}{\color{black}$\lrcorner$}",very near start]}\fi\arrow[r,"{##5}"]\ifx#9l{\arrow[d,equal,"{##6}"']}\else{\arrow[d,"{##6}"']}\fi\&{##2}\ifx#9r{\arrow[d,equal,"{##7}"]}\else{\arrow[d,"{##7}"]}\fi\ifx#2l{\arrow[ld,Rightarrow,shorten <=#6ex,shorten >=#7ex,"{#5}"{pos=#8}]}\fi\\
				{##3}\ifx#9d{\arrow[r,equal,"{##8}"']}\else{\arrow[r,"{##8}"']}\fi\ifx#2o{\arrow[ur,Rightarrow,shorten <=#6ex,shorten >=#7ex,"{#5}"{pos=#8}]}\fi\&{##4}
		\end{cd}} 
		\foosq*[l][5][5][\operatorname{lax^{cart}}][2.7][2.2][0.52]{\ensuremath{\int\ensuremath{^{\operatorname{op}}} \hspace{-0.35ex} F}}{\1}{\ensuremath{\mathpzc{B}}\xspace}{\ensuremath{\mathpzc{Cat}}\xspace}{}{\mathcal{G}\mkern-1.4mu\left(F\right)}{\1}{F}
		\end{eqD*}

\label{needof2catlax}
		\textrm{Proposition}~\ref{laxnatinsidegrothconstr} forces us to move out of $2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace$ in order to capture the $2$-category of elements (but also just the usual Grothendieck construction) from an abstract point of view. Indeed, we need to at least admit lax natural transformations as $2$-cells. If we wish to recover the Grothendieck construction of pseudofunctors or of general lax functors into $\ensuremath{\mathpzc{Cat}}\xspace$, we also need to admit lax functors as $1$-cells of our ambient. We will just consider strict $2$-functors for simplicity, but we actually expect everything to hold for lax functors as well.

		We thus consider the lax $3$-category $2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace_{\hspace{-1\horspace}\operatorname{lax}}$ of $2$-categories, $2$-functors, lax natural transformations and modifications. In~\cite{lambert_discretetwofib}, Lambert has indeed proved that this forms a lax $3$-category, i.e.\ a category enriched over the cartesian closed $1$-category of $2$-categories and normal lax functors. The idea to use $2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace_{\hspace{-1\horspace}\operatorname{lax}}$ is reinforced by the fact that Buckley, in~\cite{buckley_fibredtwocatandbicat} (continuing the work of Bakovi\'c's~\cite{bakovic_fibrofbicat}), found the need to consider trihomomorphisms $F\:\ensuremath{\mathpzc{B}}\xspace\ensuremath{^{\operatorname{coop}}}\to 2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace_{\hspace{-1\horspace}\operatorname{lax}}$ in order to capture non-split Hermida's $2$-fibrations (\cite{hermida_somepropoffibasafibredtwocat}) via a suitable Grothendieck construction.

		We should keep in mind that $2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace_{\hspace{-1\horspace}\operatorname{lax}}$ has no underlying $2$-category, since the interchange rule now only holds in a lax version, in the sense that we have a modification between the two possible lax natural transformations. Indeed, consider two lax natural transformations
		\begin{cd}
			\ensuremath{\mathpzc{A}}\xspace\arrow[r,bend left,"{F}",""'{name=A}]\arrow[r,bend right,"{G}"',""{name=B}]\&\ensuremath{\mathpzc{B}}\xspace \arrow[r,bend left,"{H}",""'{name=C}]\arrow[r,bend right,"{K}"',""{name=D}]\&\ensuremath{\mathpzc{C}}\xspace;
			\arrow[from=A,to=B,Rightarrow,"{\alpha}"]
			\arrow[from=C,to=D,Rightarrow,"{\beta}"]
		\end{cd}
		Then for every $A\in \ensuremath{\mathpzc{A}}\xspace$, the component $\alpha_A$ is a morphism $F(A)\xrightarrow[]{}G(A)$ in $\ensuremath{\mathpzc{B}}\xspace$ and we can consider the structure $2$-cell $\beta_{\alpha_A}$ of $\beta$ on such morphism
		\begin{cd}[4.75][4.75]
			H(F(A))\arrow[r,"{\beta_{F(A)}}"]\arrow[d,"{H(\alpha_A)}"']\& K(F(A))\arrow[d,"{K(\alpha_A)}"]\arrow[ld,Rightarrow,"{\beta_{\alpha_{A}}}",shorten <=2.7ex,shorten >=2.2ex]\\
			H(G(A))\arrow[r,"{\beta_{G(A)}}"']\& K(G(A))
		\end{cd}
		The $\beta_{\alpha_A}$'s collect into a modification $\beta_\alpha$ by lax naturality of $\beta$.

\label{exampletwosetenrichment}
		Consider $\ensuremath{\mathpzc{V}}\xspace=\ensuremath{\mathpzc{Set}}\xspace$. Then $2$-$\ensuremath{\mathpzc{Set}}\xspace$-enriched categories, functors, natural transformations and modifications are, respectively, bicategories, lax functors, lax natural transformations and modifications.

		We will think of $2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace_{\hspace{-1\horspace}\operatorname{lax}}$ as the lax $3$-category of $2$-$\ensuremath{\mathpzc{Set}}\xspace$-enriched categories, restricted to strict weakly enriched categories and functors for simplicity.

\label{remnametwosetenrichedgroth}
		We can now think of the $2$-category of elements construction as the {\itshape $2$-$\ensuremath{\mathpzc{Set}}\xspace$-enriched Grothendieck construction}. It takes enriched presheaves with values in $\ensuremath{{\ensuremath{\mathpzc{Set}}\xspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace}\xspace=\ensuremath{\mathpzc{Cat}}\xspace$, that is the base of the weak enrichment we consider, and converts them into discrete $2$-opfibrations, that can be seen as {\itshape $2$-$\ensuremath{\mathpzc{Set}}\xspace$-opfibrations}.

		In future work, we will explore how we can generalize this to more general monoidal categories $\ensuremath{\mathpzc{V}}\xspace$ in the place of $\ensuremath{\mathpzc{Set}}\xspace$, thus obtaining an enriched Grothendieck construction. In particular, we believe that for this the $2$-$\ensuremath{\mathpzc{Set}}\xspace$-enrichment should be distinguished from the ordinary $\ensuremath{\mathpzc{Cat}}\xspace$-enrichment; we actually expect the latter to be less useful.

\label{defweakkanextensionlaxthreecat}
		A diagram
		\begin{cd}[5][4]
			\ensuremath{\mathpzc{B}}\xspace \arrow[rr,"{F}"]\arrow[d,"{K}"']\&\arrow[dl,Rightarrow,shift right=0.75ex,"{\lambda}"{pos=0.355, inner sep= 0.35ex},shorten <=1.45ex,shorten >= 3ex]\& \ensuremath{\mathpzc{C}}\xspace \\
			\ensuremath{\mathpzc{A}}\xspace\arrow[rru,"L"']
		\end{cd}
		in a lax $3$-category $\ensuremath{\mathpzc{Q}}\xspace$ (that is a category enriched over the $1$-category of $2$-categories and lax functors), exhibits $L$ as the {\itshape weak left Kan extension of $F$ along $K$}, written $L={\operatorname{lan}_{\hspace{0.2ex}K}{F}}$, if pasting with $\lambda$ gives an isomorphism of categories
		\begin{equation}\label{eqweakkanextensionlaxthreecat}
			{{\ensuremath{\mathpzc{Q}}\xspace}\left({\ensuremath{\mathpzc{A}}\xspace},\hspace{1\horspace}{\ensuremath{\mathpzc{C}}\xspace}\right)}\left({L},\hspace{1\horspace}{U}\right)\cong {{\ensuremath{\mathpzc{Q}}\xspace}\left({\ensuremath{\mathpzc{B}}\xspace},\hspace{1\horspace}{\ensuremath{\mathpzc{C}}\xspace}\right)}\left({F},\hspace{1\horspace}{U\circ K}\right)
		\end{equation}
		for every $U\in {\ensuremath{\mathpzc{Q}}\xspace}\left({\ensuremath{\mathpzc{A}}\xspace},\hspace{1\horspace}{\ensuremath{\mathpzc{C}}\xspace}\right)$ (the $2$-naturality in $U$ is granted automatically).

Cartesian-marked oplax with respect to the marking described in \textrm{Remark}~\ref{fromgrothisnotrestrictive}, which we can call {\itshape the trivial marking} and denote as $\operatorname{triv}$, coincides with strict $2$-naturality. We can then rephrase \textrm{Theorem}~\ref{redoplaxnormalconical} as follows:

		\noindent \textit{In $2\hspace{2\horspace}\mbox{-}\ensuremath{\mathpzc{Cat}}\xspace_{\hspace{-1\horspace}\operatorname{lax}}$ every trivially-marked weighted $2$-colimit can be equivalently expressed as a marked trivially-weighted $2$-colimit. More precisely}
		$$\operatorname{oplax}_{\operatorname{triv}}^{\operatorname{cart}}\mbox{-}\hspace{1.5\horspace}{\operatorname{colim}}^{W}\hspace{1.0\horspace}{F}\hspace{2\horspace}\cong\hspace{2\horspace} \operatorname{oplax}_{W}^{\operatorname{cart}}\mbox{-}\hspace{1.5\horspace}{\operatorname{colim}}^{\Delta 1}\hspace{1.0\horspace}{\left(F\circ \mathcal{G}\mkern-1.4mu\left(W\right)\right)}$$

\label{defoplaxnlax}
